head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.delLowP = 0;
scwin.stFocusGrid = false;
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 현재 별도 초기화 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시점 — 현재 별도 해제 로직 없음.
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name listSync
 * @description 대표이사변경 목록(MxDataSet)을 조회(/ceochg.do)하고 완료 후 구 콜백(MxDataSet_OnLoadCompleted)으로 총건수를 갱신한다.
 * @returns {void}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/ceochg.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

};

/*---------------------------------------------------------------------------------------------------------*/
scwin.js_com_Isurcd; // 발행사코드
scwin.js_com_Isurnm; // 발행사명

scwin.js_com_market = frame.Provider("/top").ps_market; // 운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market !== "1" && scwin.js_com_market !== "2") scwin.js_com_market = "";
// if (typeof(js_com_market)=="undefined") {js_com_market = ""; }else{ js_com_market = js_market; }
scwin.js_com_left;
scwin.js_com_top;

/**
 * @method
 * @name IsurTagetPos
 * @description 발행사 검색 그리드(Grd_com_isur)의 표시 위치(js_com_left/js_com_top)를 대상 컴포넌트 좌표 기준으로 계산한다(Tg "G"면 그리드용 오프셋 적용).
 * @param {Object} grdObj 발행사코드 컴포넌트
 * @param {Object} grdObj2 발행사명 컴포넌트
 * @param {String} Tg 위치 산출 구분("G": 그리드, 그 외: 편집)
 * @returns {void}
 * @hidden N
 * @example $c.cm.IsurTagetPos(isur_cd, isur_nm, "G");
 */
$c.cm.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    let cL = 7;
    let cT = 53;
    if (Tg === "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = scwin.js_com_left.substring(0, scwin.js_com_left.length - 2);
    scwin.js_com_left = eval(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = scwin.js_com_top.substring(0, scwin.js_com_top.length - 2);
    scwin.js_com_top = eval(scwin.js_com_top) + cT;
};
/**
 * @method
 * @name fn_com_grid_pos
 * @description 발행사코드/발행사명 대상 컴포넌트를 보관하고 발행사 검색 그리드(Grd_com_isur)를 계산된 위치로 이동한다.
 * @param {Object} grdObj 발행사코드 컴포넌트
 * @param {Object} grdObj2 발행사명 컴포넌트
 * @returns {void}
 * @hidden N
 * @example $c.cm.fn_com_grid_pos(isur_cd, isur_nm);
 */
$c.cm.fn_com_grid_pos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; // 발행사코드
    scwin.js_com_Isurnm = grdObj2; // 발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;
};
/**
 * @method
 * @name IsurcdSearch
 * @description 발행회사검색 팝업(ULDCOM00007)을 열고 리턴값("코드^명")을 기존 콜백 계약(isurSearch_Rtn)에 연결한다.
 * @param {Object} grdObj 발행사코드 컴포넌트
 * @param {Object} grdObj2 발행사명 컴포넌트
 * @returns {void}
 * @hidden N
 * @example $c.cm.IsurcdSearch(isur_cd, isur_nm);
 */
$c.cm.IsurcdSearch = async function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj; // 발행사코드
    scwin.js_com_Isurnm = grdObj2; // 발행사명
    scwin.IsurTagetPos(grdObj, grdObj2, 'E');

    const options = {
        id: "ULDCOM00007",
        title: "발행회사검색창",
        type: "pageFramePopup",
        width: "295px",
        height: "400px"
    };

    const data = {
};

    const result = await $c.win.openPopup("/common/ULDCOM00007.gfm", options, data);
    // 팝업(ULDCOM00007) 리턴 "코드^명" 을 기존 콜백 계약(isurSearch_Rtn)에 연결
    if (result) {
        $c.cm.isurSearch_Rtn(...String(result).split("^"));
    }
};
/**
 * @method
 * @name isurSearch_Rtn
 * @description 발행회사검색 결과(발행사코드/발행사명)를 보관된 대상 컴포넌트에 설정한다.
 * @param {String} pJongCode 발행사코드
 * @param {String} pJongNm 발행사명
 * @returns {void}
 * @hidden N
 * @example $c.cm.isurSearch_Rtn("00593", "KRX");
 */
$c.cm.isurSearch_Rtn = function(pJongCode, pJongNm) {
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);
};
/**
 * @method
 * @name fn_com_isur_sync
 * @description 발행사코드 목록 데이터셋(MxDataSet_com_isur)을 /isurcd.do 로 조회한다.
 * @returns {void}
 * @hidden N
 * @example $c.cm.fn_com_isur_sync();
 */
$c.cm.fn_com_isur_sync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/isurcd.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

};
/**
 * @method
 * @name fn_com_isur
 * @description 발행사 검색 그리드를 숨기고 대상 컴포넌트 위치를 지정한 뒤 발행사코드 데이터셋을 조회한다(fn_com_isur_sync 연계).
 * @param {Object} grdObj 발행사코드 컴포넌트
 * @param {Object} grdObj2 발행사명 컴포넌트
 * @returns {void}
 * @hidden N
 * @example $c.cm.fn_com_isur(isur_cd, isur_nm);
 */
$c.cm.fn_com_isur = async function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    scwin.fn_com_grid_pos(grdObj, grdObj2);
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);

    scwin.fn_com_isur_sync();
};
/**
 * @method
 * @name fn_com_Confirm_set
 * @description 발행사 검색 그리드 선택 행의 발행사코드(ISUR_CD)/회사약명(COM_ABBRV)을 대상 컴포넌트에 설정하고 그리드를 숨긴다.
 * @returns {void}
 * @hidden N
 * @example $c.cm.fn_com_Confirm_set();
 */
$c.cm.fn_com_Confirm_set = function() {

    const pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "ISUR_CD");

    const pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "COM_ABBRV");
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);

    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};
/**
 * @method
 * @name fn_com_isur_nm
 * @description 입력값(숫자면 발행사코드, 그 외 회사약명)으로 발행사 데이터셋을 정렬한 뒤 입력값 이상이 되는 첫 행을 탐색한다(구 스크롤 트릭은 미이관).
 * @param {Number} keyCode 키 코드(현재 미사용)
 * @returns {void}
 * @hidden N
 * @example $c.cm.fn_com_isur_nm(13);
 */
$c.cm.fn_com_isur_nm = function(keyCode) {
    let cnt = 0;
    const len = scwin.js_com_Isurcd.getValue().length;
    const txtVal = scwin.js_com_Isurcd.getValue().toUpperCase();
    let foColum = 1;
    if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum === 1) {
        MxDataSet_com_isur.sort("COM_ABBRV", 0);
        for (let i = 0; i < MxDataSet_com_isur.getRowCount(); i++) {

            const name = MxDataSet_com_isur.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.sort("ISUR_CD", 0);
        for (let i = 0; i < MxDataSet_com_isur.getRowCount(); i++) {

            const name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }
    // 구 Rowposition(cnt+11→cnt) 스크롤 트릭 — 대상 그리드(Grd_com_isur) 마크업 부재로 포커스 전환 대상 없음(발행사 검색은 ULDCOM00007 팝업으로 대체)
};

/*-----------------------------------------------------------------------------------------------------*/
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description 목록 조회 완료 콜백 — 총건수를 textbox_1 에 표시한다.
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount());
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
};

/**
 * @method
 * @name gform_onload
 * @description 구 gform onload — 대표이사변경 목록(MxDataSet)을 조회한 뒤 일자 기본값(toDaySet)과 발행사 자동완성(fn_com_isur)을 설정한다.
 * @returns {void}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    // PanelToGroupBox_02(panel_2);
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(MxDataSet.getRowCount()); // 구 콜백 연결

    toDaySet(txb_date1);

    toDaySet(txb_date2);
    scwin.fn_com_isur(isur_cd, isur_nm);
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 버튼 클릭 — 공시접수일자(시작/종료) 입력을 확인한 뒤 목록을 조회한다(listSync).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_sys_search ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_sys_search_onclick = function(e) {
    if (txb_date1.getValue() !== "" && txb_date2.getValue() !== "") {
        scwin.listSync(); // alert();

    } else {
        alert("일자를 지정하십시요");
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description 달력 버튼 클릭 — 공시접수일자(시작, txb_date1) 달력 팝업을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_cal ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_cal_onclick = function(e) {

    popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');

};

/**
 * @method
 * @name image_6_onclick
 * @description 발행회사 검색 버튼 클릭 — 발행회사검색 팝업을 연다(IsurcdSearch).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (image_6 ev:onclick 바인딩으로 자동 호출)
 */
scwin.image_6_onclick = function(e) {
    scwin.IsurcdSearch(isur_cd, isur_nm);
};

/**
 * @method
 * @name image_2_onclick
 * @description 달력 버튼 클릭 — 공시접수일자(종료, txb_date2) 달력 팝업을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (image_2 ev:onclick 바인딩으로 자동 호출)
 */
scwin.image_2_onclick = function(e) {

    popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');

};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 「엑셀다운로드」 버튼 클릭 — 그리드(MxGrid_1) 내용을 엑셀로 다운로드한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example (btn_toExcel ev:onclick 바인딩으로 자동 호출)
 */
scwin.btn_toExcel_onclick = function(e) {

    MxGrid_1.GridToExcel("대표이사변경", "", "2");
};

/**
 * @method
 * @name MxGrid_1_OnClick
 * @description 그리드 클릭 — 클릭 행 인덱스를 delLowP 에 보관한다(접수번호 조회는 구 로직 잔존).
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.MxGrid_1_OnClick(0, "ACPT_NO");
 */
scwin.MxGrid_1_OnClick = function(row, colid) {
    scwin.delLowP = row;

    const sCd = MxDataSet.getCellData(row, "ACPT_NO");
};
